-- 2) Eight numbered sections, each carrying EN + UR synthesis.
INSERT OR REPLACE INTO ar_ling_lexicon_entry_sections (id, root_entry_id, source_slug, root_text, root_norm, section_seq, heading_ar, heading_norm, section_type, text_ar, page_no, translation_en, translation_ur) VALUES ('sec_mfr_byn_1', 're_mfr_6401dfb6ff09bfea', 'ketabonline_al_raghib_mufradat', 'بين', 'بين', 1, 'الأصل والمعنيان', NULL, 'definition', (SELECT text_plain FROM ar_ling_lexicon_blocks WHERE id = 'blk_mfr2_p1'), 156, '<span class="ar">بَيْن</span> is set for the interval between two things and their midst. He said: "And We placed between them a cultivated field" <span class="r">[الكهف ١٨:٣٢]</span>. It is said: <span class="ar">بانَ</span> such-and-such — it separated, and what was concealed of it appeared. Since separation and disclosure were both considered in it, it came to be used for each alone: a deep-bottomed well is called <span class="ar">بَيُون</span>, for the distance between rim and floor, since its rope is severed from its owner''s hand. And <span class="ar">بانَ الصُّبْحُ</span>: the dawn appeared. And His saying "indeed your <span class="ar">بَيْن</span> is severed" <span class="r">[الأنعام ٦:٩٤]</span> means: your bond. Its verification: the wealth, the clan, and the deeds you relied upon are lost to you — echoing "the Day when neither wealth nor sons avail" <span class="r">[الشعراء ٢٦:٨٨]</span>, and "you have come to Us alone" <span class="r">[الأنعام ٦:٩٤]</span>.', 'بَین اُس خلا کے لیے وضع کیا گیا ہے جو دو چیزوں کے درمیان اور ان کے وسط میں ہو۔ فرمایا: ﴿اور ہم نے ان دونوں کے درمیان ایک کھیتی بنا دی﴾ [الکہف:٣٢]۔ کہا جاتا ہے: بانَ فلاں چیز — وہ جدا ہوئی اور اس کا چھپا حصہ ظاہر ہو گیا۔ چونکہ اس میں جدائی اور ظہور دونوں ملحوظ ہیں، ہر ایک کے لیے الگ استعمال ہونے لگا: گہرے کنویں کو "بَیُون" کہتے ہیں کیونکہ اس کی رسی مالک کے ہاتھ سے جدا ہو جاتی ہے۔ "بانَ الصبحُ": صبح ظاہر ہوئی۔ ﴿بےشک تمہارا بَین منقطع ہو گیا﴾ [الانعام:٩٤]، یعنی تمہارا رشتہ۔ تحقیق: وہ مال، قبیلہ اور اعمال جن پر بھروسا تھا جاتے رہے — ﴿جس دن نہ مال نہ بیٹے فائدہ دیں﴾ [الشعراء:٨٨]؛ اور ﴿تم ہمارے پاس اکیلے آ گئے﴾ [الانعام:٩٤]۔');
INSERT OR REPLACE INTO ar_ling_lexicon_entry_sections (id, root_entry_id, source_slug, root_text, root_norm, section_seq, heading_ar, heading_norm, section_type, text_ar, page_no, translation_en, translation_ur) VALUES ('sec_mfr_byn_2', 're_mfr_6401dfb6ff09bfea', 'ketabonline_al_raghib_mufradat', 'بين', 'بين', 2, 'اسمًا وظرفًا · القراءات', NULL, 'definition', (SELECT text_plain FROM ar_ling_lexicon_blocks WHERE id = 'blk_mfr2_p2'), 156, '<span class="ar">بَيْن</span> is used now as a noun, now as an adverb: whoever reads <span class="ar">بَيْنُكُم</span> (nominative) <span class="r">[الأنعام ٦:٩٤]</span> takes it as a noun; whoever reads <span class="ar">بَيْنَكُم</span> takes it as an indeclinable adverb left with the <span class="ar">فَتْحة</span>. Adverbial: "do not put yourselves forward before God and His Messenger" <span class="r">[الحجرات ٤٩:١]</span>; "offer a charity before your private talk" <span class="r">[المجادلة ٥٨:١٢]</span>; "judge between us in truth" <span class="r">[ص ٣٨:٢٢]</span>; "when the two reached the junction between them" <span class="r">[الكهف ١٨:٦١]</span> — possibly a <span class="ar">مَصْدَر</span>, the place of parting. "And if he is of a people with whom you have a covenant" <span class="r">[النساء ٤:٩٢]</span>.', '"بَین" کبھی اسم، کبھی ظرف؛ جس نے ﴿بَینُکم﴾ [الانعام:٩٤] پڑھا اس نے اسم بنایا، جس نے ﴿بَینَکم﴾ پڑھا اس نے غیر متمکن ظرف بنایا جو فتحہ پر ہے۔ ظرف کی مثال: ﴿اللہ اور اس کے رسول کے آگے نہ بڑھو﴾ [الحجرات:١]؛ ﴿سرگوشی سے پہلے صدقہ دو﴾ [المجادلہ:١٢]؛ ﴿ہمارے درمیان حق سے فیصلہ کر﴾ [ص:٢٢]؛ ﴿جب وہ دونوں اپنے ملاپ کی جگہ پہنچے﴾ [الکہف:٦١] — یہ مصدر بھی ہو سکتا ہے، یعنی جدائی کی جگہ۔ ﴿اور اگر وہ ایسی قوم میں سے ہو جن سے تمہارا معاہدہ ہو﴾ [النساء:٩٢]۔');
INSERT OR REPLACE INTO ar_ling_lexicon_entry_sections (id, root_entry_id, source_slug, root_text, root_norm, section_seq, heading_ar, heading_norm, section_type, text_ar, page_no, translation_en, translation_ur) VALUES ('sec_mfr_byn_3', 're_mfr_6401dfb6ff09bfea', 'ketabonline_al_raghib_mufradat', 'بين', 'بين', 3, 'قاعدة الاستعمال · بين يدي · ذات البين', NULL, 'definition', (SELECT text_plain FROM ar_ling_lexicon_blocks WHERE id = 'blk_mfr2_p3'), 156, '<span class="ar">بَيْن</span> is used only where there is distance (between two towns) or a count of two-plus; it is not annexed to a singular unless repeated: "between us and you is a partition" <span class="r">[فصلت ٤١:٥]</span>, "set between us and you an appointment" <span class="r">[طه ٢٠:٥٨]</span>. It is said: this thing is <span class="ar">بَيْنَ يَدَيْكَ</span> (before your hands) = ahead of you; or = near you. So: "then I will surely come to them from before them" <span class="r">[الأعراف ٧:١٧]</span>; "His is what is before us and behind us" <span class="r">[مريم ١٩:٦٤]</span>; "We placed before them a barrier and behind them a barrier" <span class="r">[يس ٣٦:٩]</span>; "confirming what came before it of the Torah" <span class="r">[المائدة ٥:٤٦]</span>; "has the Reminder been sent down upon him from among us?" <span class="r">[ص ٣٨:٨]</span> = from all of us; "nor in what came before it" <span class="r">[سبأ ٣٤:٣١]</span> = the Gospel; and "fear God and set right the ties between you" <span class="r">[الأنفال ٨:١]</span> = uphold the <span class="ar">ذاتَ البَيْن</span> — the kinship, connection, and affection that join you.', '"بین" صرف مسافت والی چیز میں، جیسے دو شہروں کے درمیان، یا دو یا زیادہ کے عدد میں؛ واحد کی طرف اضافت صرف تکرار سے: ﴿ہمارے اور تمہارے درمیان پردہ ہے﴾ [فصلت:٥]، ﴿ہمارے اور اپنے درمیان وعدہ مقرر کر﴾ [طٰہٰ:٥٨]۔ "بین یدیک" = تیرے آگے، یا تیرے قریب۔ ﴿پھر میں ان کے آگے سے آؤں گا﴾ [الاعراف:١٧]؛ ﴿اسی کا ہے جو ہمارے آگے اور پیچھے ہے﴾ [مریم:٦٤]؛ ﴿ہم نے ان کے آگے پیچھے دیوار بنائی﴾ [یٰسٓ:٩]؛ ﴿توراۃ کی تصدیق کرنے والی جو اس سے پہلے تھی﴾ [المائدہ:٤٦]؛ ﴿کیا ہم میں سے اسی پر ذکر نازل ہوا؟﴾ [ص:٨] = ہم سب میں سے؛ ﴿نہ اس سے پہلے کی انجیل پر﴾ [سبأ:٣١]؛ ﴿اللہ سے ڈرو اور آپس کے تعلقات درست کرو﴾ [الانفال:١]۔');
INSERT OR REPLACE INTO ar_ling_lexicon_entry_sections (id, root_entry_id, source_slug, root_text, root_norm, section_seq, heading_ar, heading_norm, section_type, text_ar, page_no, translation_en, translation_ur) VALUES ('sec_mfr_byn_4', 're_mfr_6401dfb6ff09bfea', 'ketabonline_al_raghib_mufradat', 'بين', 'بين', 4, 'بينما / بينا · ظرف زمان', NULL, 'definition', (SELECT text_plain FROM ar_ling_lexicon_blocks WHERE id = 'blk_mfr2_p4'), 156, '<span class="ar">ما</span> or the alif is added to <span class="ar">بَيْن</span>, making it like <span class="ar">حِين</span> ("when/while"): <span class="ar">بَيْنَما</span> Zayd does such-and-such, <span class="ar">بَيْنا</span> he does such-and-such. The poet said: "While the armored knights were closing on him, and he evaded them — one day a bold, dauntless one was granted power over him." <i>(<span class="ar">شاهِد</span> — <span class="ar">أبو ذؤيب الهُذلي</span>, note 3)</i>', '"بین" پر "ما" یا الف بڑھانے سے یہ "حین" کے درجے میں آ جاتا ہے: بَینَما زید ایسا کرتا ہے، بَینا وہ ایسا کرتا ہے۔ شاعر نے کہا: "جس دوران زرہ پوش اسے گھیرے تھے اور وہ بچ نکلتا تھا... ایک دن ایک دلیر بےباک کو اس پر غلبہ دیا گیا۔" (شاہد — ابو ذؤیب ہذلی، حاشیہ ٣)');
INSERT OR REPLACE INTO ar_ling_lexicon_entry_sections (id, root_entry_id, source_slug, root_text, root_norm, section_seq, heading_ar, heading_norm, section_type, text_ar, page_no, translation_en, translation_ur) VALUES ('sec_mfr_byn_5', 're_mfr_6401dfb6ff09bfea', 'ketabonline_al_raghib_mufradat', 'بين', 'بين', 5, 'عائلة الفعل · مُبيَّنة ومُبيِّنة', NULL, 'definition', (SELECT text_plain FROM ar_ling_lexicon_blocks WHERE id = 'blk_mfr2_p5'), 156, 'It is said: <span class="ar">بَانَ، اسْتَبَانَ، تَبَيَّنَ</span> — like <span class="ar">عَجِلَ، اسْتَعْجَلَ، تَعَجَّلَ</span> (to hasten) — and <span class="ar">بَيَّنْتُهُ</span> (I made it clear). God said: "it has become clear to you from their dwellings" <span class="r">[العنكبوت ٢٩:٣٨]</span>; "it became clear to you how We dealt with them" <span class="r">[إبراهيم ١٤:٤٥]</span>; "that the way of the criminals become clear" <span class="r">[الأنعام ٦:٥٥]</span>; "right guidance has become distinct from error" <span class="r">[البقرة ٢:٢٥٦]</span>; "We have made the signs clear to you" <span class="r">[آل عمران ٣:١١٨]</span>; "that I make clear to you some of what you differ in" <span class="r">[الزخرف ٤٣:٦٣]</span>; "We sent down the Reminder that you make clear to the people what was sent to them" <span class="r">[النحل ١٦:٤٤]</span>; "that he make clear to them what they differ in" <span class="r">[النحل ١٦:٣٩]</span>; "in it are clear signs" <span class="r">[آل عمران ٣:٩٧]</span>; "guidance for the people, and clear proofs" <span class="r">[البقرة ٢:١٨٥]</span>. And: an <span class="ar">آية</span> is <span class="ar">مُبَيَّنة</span> (made clear — passive) or <span class="ar">مُبَيِّنة</span> (clarifying — active); hence both plurals.', 'کہا جاتا ہے: بانَ، استبانَ، تبیّنَ — عجِلَ، استعجلَ، تعجّلَ کی طرح — اور بیّنتُہ۔ اللہ نے فرمایا: ﴿ان کی بستیوں سے تمہارے لیے واضح ہو چکا﴾ [العنکبوت:٣٨]؛ ﴿تمہارے لیے واضح ہوا کہ ہم نے ان کے ساتھ کیا کیا﴾ [ابراہیم:٤٥]؛ ﴿اور تاکہ مجرموں کا راستہ واضح ہو﴾ [الانعام:٥٥]؛ ﴿رشد گمراہی سے واضح ہو چکا﴾ [البقرہ:٢٥٦]؛ ﴿ہم نے آیات واضح کر دیں﴾ [آل عمران:١١٨]؛ ﴿تاکہ میں تمہارے اختلافی امور واضح کروں﴾ [الزخرف:٦٣]؛ ﴿ہم نے ذکر نازل کیا تاکہ تو لوگوں کے لیے واضح کرے﴾ [النحل:٤٤]؛ ﴿تاکہ وہ اختلافی امر واضح کرے﴾ [النحل:٣٩]؛ ﴿اس میں واضح نشانیاں ہیں﴾ [آل عمران:٩٧]؛ ﴿ہدایت اور واضح دلائل﴾ [البقرہ:١٨٥]۔ آیت "مُبَیَّنة" (جسے واضح کیا گیا) یا "مُبَیِّنة" (جو خود واضح کرے)؛ دونوں جمعیں۔');
INSERT OR REPLACE INTO ar_ling_lexicon_entry_sections (id, root_entry_id, source_slug, root_text, root_norm, section_seq, heading_ar, heading_norm, section_type, text_ar, page_no, translation_en, translation_ur) VALUES ('sec_mfr_byn_6', 're_mfr_6401dfb6ff09bfea', 'ketabonline_al_raghib_mufradat', 'بين', 'بين', 6, 'البَيِّنة', NULL, 'definition', (SELECT text_plain FROM ar_ling_lexicon_blocks WHERE id = 'blk_mfr2_p6'), 156, '<span class="ar">البَيِّنة</span> = the manifest indication, rational or sensory. The two witnesses are called <span class="ar">بَيِّنة</span>, from his saying (ﷺ): "the proof (<span class="ar">بَيِّنة</span>) is upon the claimant, and the oath upon the one who denies." And: "is he who is upon a clear proof from his Lord..." <span class="r">[هود ١١:١٧]</span>; "that he who perished might perish upon a clear proof, and he who lived might live upon a clear proof" <span class="r">[الأنفال ٨:٤٢]</span>; "their messengers came to them with clear proofs" <span class="r">[الروم ٣٠:٩]</span>.', '"البَیِّنة": واضح دلیل، عقلی یا محسوس۔ دو گواہوں کو "بیّنہ" کہا گیا آپ ﷺ کے قول سے: «گواہی مدعی پر ہے اور قسم انکار کرنے والے پر»۔ ﴿کیا وہ جو اپنے رب کی طرف سے واضح دلیل پر ہے...﴾ [ھود:١٧]؛ ﴿تاکہ جو ہلاک ہو واضح دلیل سے ہلاک ہو اور جو زندہ رہے واضح دلیل سے زندہ رہے﴾ [الانفال:٤٢]؛ ﴿ان کے رسول واضح دلائل کے ساتھ آئے﴾ [الروم:٩]۔');
INSERT OR REPLACE INTO ar_ling_lexicon_entry_sections (id, root_entry_id, source_slug, root_text, root_norm, section_seq, heading_ar, heading_norm, section_type, text_ar, page_no, translation_en, translation_ur) VALUES ('sec_mfr_byn_7', 're_mfr_6401dfb6ff09bfea', 'ketabonline_al_raghib_mufradat', 'بين', 'بين', 7, 'البَيان · ضربان: بالتسخير وبالاختبار', NULL, 'definition', (SELECT text_plain FROM ar_ling_lexicon_blocks WHERE id = 'blk_mfr2_p7'), 156, '<span class="ar">البَيان</span> = uncovering a thing; broader than speech, since speech is peculiar to man; whatever is clarified by it is called <span class="ar">بَيان</span>. Some said: <span class="ar">البَيان</span> is of two kinds — by <span class="ar">تَسْخير</span> (disposition): things that indicate a state through the marks of craftsmanship; and by <span class="ar">اخْتِبار</span> (deliberate signification): speech, writing, or gesture. By state: "he is to you a manifest enemy" <span class="r">[الزخرف ٤٣:٦٢]</span>; "bring us a manifest authority" <span class="r">[إبراهيم ١٤:١٠]</span>. By deliberate signification: "ask the people of the Reminder if you do not know — with clear proofs and scriptures" <span class="r">[النحل ١٦:٤٣-٤٤]</span>; and speech is called <span class="ar">بَيان</span> for uncovering the intended meaning: "this is an exposition for mankind" <span class="r">[آل عمران ٣:١٣٨]</span>.', '"البَیان": کسی چیز کا انکشاف، نطق سے عام تر کیونکہ نطق انسان کے ساتھ خاص ہے۔ بعض نے کہا: بیان دو قسم: تسخیر سے — وہ چیزیں جو صنعت کے آثار سے کسی حال پر دلالت کریں؛ اور اختبار سے — نطق، کتابت یا اشارہ۔ بیانِ حال: ﴿بےشک وہ تمہارا کھلا دشمن ہے﴾ [الزخرف:٦٢]؛ ﴿ہمارے پاس واضح دلیل لاؤ﴾ [ابراہیم:١٠]۔ بیانِ اختبار: ﴿اہلِ ذکر سے پوچھو اگر نہیں جانتے — واضح دلائل اور کتابوں کے ساتھ﴾ [النحل:٤٣-٤٤]؛ کلام کو بیان کہا گیا کیونکہ وہ مقصود معنی ظاہر کرتا ہے: ﴿یہ لوگوں کے لیے بیان ہے﴾ [آل عمران:١٣٨]۔');
INSERT OR REPLACE INTO ar_ling_lexicon_entry_sections (id, root_entry_id, source_slug, root_text, root_norm, section_seq, heading_ar, heading_norm, section_type, text_ar, page_no, translation_en, translation_ur) VALUES ('sec_mfr_byn_8', 're_mfr_6401dfb6ff09bfea', 'ketabonline_al_raghib_mufradat', 'بين', 'بين', 8, 'بيانُ المُجمَل · المُبين', NULL, 'definition', (SELECT text_plain FROM ar_ling_lexicon_blocks WHERE id = 'blk_mfr2_p8'), 156, 'What explains the general (<span class="ar">مُجْمَل</span>) and ambiguous (<span class="ar">مُبْهَم</span>) in speech is also called <span class="ar">بَيان</span>: "then indeed upon Us is its exposition" <span class="r">[القيامة ٧٥:١٩]</span>. And: <span class="ar">بَيَّنْتُهُ / أَبَنْتُهُ</span> (I made it clear) — when you give it a bayān that uncovers it: "that you make clear to the people what was sent to them" <span class="r">[النحل ١٦:٤٤]</span>. And: "a manifest warner" <span class="r">[ص ٣٨:٧٠]</span>; "indeed this is the manifest trial" <span class="r">[الصافات ٣٧:١٠٦]</span>; "he can hardly make himself clear" <span class="r">[الزخرف ٤٣:٥٢]</span> = <span class="ar">يُبَيِّنُ</span>; "and in dispute he is not clear" <span class="r">[الزخرف ٤٣:١٨]</span>.', 'کلام میں مجمل و مبہم کی شرح کرنے والی چیز کو بھی بیان کہا جاتا ہے: ﴿پھر بےشک اس کا بیان ہمارے ذمے ہے﴾ [القیامہ:١٩]۔ بیّنتُہ / أبنتُہ = جب اسے ایسا بیان دو جو اسے کھول دے: ﴿تاکہ تو لوگوں کے لیے واضح کرے﴾ [النحل:٤٤]۔ ﴿واضح ڈرانے والا﴾ [ص:٧٠]؛ ﴿بےشک یہی کھلی آزمائش ہے﴾ [الصافات:١٠٦]؛ ﴿وہ بمشکل واضح کر پاتا ہے﴾ [الزخرف:٥٢] = یبیّن؛ ﴿اور وہ جھگڑے میں واضح نہیں﴾ [الزخرف:١٨]۔');

