UPDATE ar_ling_lexicon_root_entries SET family_json = '{"meaning_core": {"ar": "بَيْنٌ — الخَلالةُ بين الشيئينِ ووسَطُهما", "en": "the interval between two things — the one core he derives everything from", "ur": "دو چیزوں کے درمیان کا وقفہ — وہی ایک بنیاد جس سے وہ سب کچھ اخذ کرتا ہے"}, "poles": [{"key": "sep", "title_ar": "الانفصال", "title_en": "separation", "forms": [{"badge": "I · ضَرَبَ", "head_html": "بَانَ · <em>يَبِينُ</em>", "masdar_html": "مصادر: <b>بَيْن · بَيْنونة · بُيون</b>", "gloss_en": "to be severed / part — <span class=\"ar\">لازِم</span>, or via <span class=\"ar\">عن</span>", "gloss_ur": "جدا ہونا — لازم، یا «عن» کے ساتھ متعدی"}, {"badge": "n.", "head_html": "البَيُون", "gloss_en": "the deep-bottomed well — his image of \"separation\"", "gloss_ur": "گہرا کنواں — «جدائی» کی اُس کی اپنی تصویر", "citation_html": "<span class=\"rf\">al-Anʿām 6:94</span> ﴿لَقَدْ تَقَطَّعَ بَيْنَكُمْ﴾ — أي وصلُكم"}]}, {"key": "disc", "title_ar": "الظهور", "title_en": "disclosure", "forms": [{"badge": "I", "head_html": "بَانَ · <em>يَبِينُ</em>", "masdar_html": "مصادر: <b>بَيان · تِبيان</b> — <span class=\"disc\">بانَ الصبحُ: ظهر</span>", "gloss_en": "to appear, to become clear — intransitive", "gloss_ur": "ظاہر ہونا، واضح ہونا (لازم)"}, {"badge": "II", "head_html": "بَيَّنَ · <em>يُبَيِّنُ</em>", "masdar_html": "مصدر: <b>تَبيين</b> · متعدٍّ", "gloss_en": "to make clear, to explain — transitive", "gloss_ur": "واضح کرنا، بیان کرنا (متعدی)", "citation_html": "<span class=\"rf\">al-Naḥl 16:44</span> ﴿لِتُبَيِّنَ لِلنَّاسِ﴾"}, {"badge": "IV", "head_html": "أَبَانَ · <em>يُبِينُ</em>", "masdar_html": "مصدر: <b>إبانة</b> → <b>مُبِين</b>", "gloss_en": "to make manifest — hence the participle", "gloss_ur": "ظاہر کر دینا؛ اِسی سے مُبِین", "citation_html": "<span class=\"rf\">al-Zukhruf 43:62</span> ﴿عَدُوٌّ مُبِينٌ﴾"}, {"badge": "V", "head_html": "تَبَيَّنَ · <em>يَتَبَيَّنُ</em>", "gloss_en": "to become evident; to ascertain", "gloss_ur": "واضح ہو جانا؛ تحقیق کرنا", "citation_html": "<span class=\"rf\">al-Baqara 2:256</span> ﴿قَدْ تَبَيَّنَ الرُّشْدُ﴾"}, {"badge": "X", "head_html": "اسْتَبَانَ · <em>يَسْتَبِينُ</em>", "gloss_en": "to seek clarity; to become distinct", "gloss_ur": "وضاحت طلب کرنا؛ نمایاں ہونا", "citation_html": "<span class=\"rf\">al-Anʿām 6:55</span> ﴿لِتَسْتَبِينَ سَبِيلُ﴾"}]}], "derivation": {"quote_ar": "«يقال: بَانَ واسْتَبَانَ وتَبَيَّنَ — نحوَ: عَجِلَ واستعجلَ وتعجّلَ — وقد بَيَّنْتُهُ.»", "en_html": "His own words bind the family: the forms <span class=\"ar\">بَانَ</span> (I), <span class=\"ar\">اسْتَبَانَ</span> (X) and <span class=\"ar\">تَبَيَّنَ</span> (V) all carry one and the same sense — exactly as “to hasten” has three forms that mean the same thing. The differing measures do not split the meaning; the whole family turns on a single core — <b>the gap between two things</b>, from which both separation (parting) and disclosure (clarity) flow.", "ur_html": "الراغب کا نکتہ: بانَ (I)، استبانَ (X) اور تبیّنَ (V) — یہ سب صیغے ایک ہی معنی رکھتے ہیں، بالکل ایسے جیسے “جلدی کرنا” کے تین صیغے ایک ہی مطلب دیتے ہیں۔ صیغوں کا فرق معنی کو تقسیم نہیں کرتا؛ پورا خاندان ایک ہی بنیاد پر گھومتا ہے: دو چیزوں کے درمیان کا وقفہ، جس سے جدائی اور وضوح دونوں نکلتے ہیں۔", "inferred_en_html": "So every Qurʾanic <span class=\"ar\">بَيْن</span> is one act of setting a gap between two things: to separate is to open the gap; to make clear is to mark the gap between truth and error. Parting and clarity are two faces of the same core.", "inferred_ur_html": "پس قرآن کا ہر «بَيْن» دو چیزوں کے درمیان وقفہ قائم کرنے کا عمل ہے: جدا کرنا وقفہ کھولنا ہے، اور واضح کرنا حق و باطل کے درمیان فرق نمایاں کرنا ہے۔ جدائی اور وضوح ایک ہی بنیاد کے دو رخ ہیں۔"}}', entry_gloss_json = '{"letters_spaced": "ب ي ن", "letters_dotted": "ب · ي · ن", "root_type_ar": "جذر ثلاثيّ أجوف يائيّ", "gloss_en": "separation · disclosure · clarity", "gloss_ar": "الانفصال · الظهور · الوضوح"}' WHERE id = 're_mfr_6401dfb6ff09bfea';
